refentry.refsect1:
&reftitle.parameters;
name
O nome da configuração a ser inspecionada, usando a mesma notação de pontos de Yaconf::get.

  &reftitle.examples;

   Exemplo de Yaconf::__debug_info


<?php
// supondo que app.ini contenha name="shop"
var_dump(Yaconf::__debug_info("app.name"));
/*
array(4) {
  ["key"]=>
  string(8) "app.name"
  ["address"]=>
  string(14) "0x7f8b1c0a3d20"
  ["val"]=>
  string(4) "shop"
  ["changed"]=>
  bool(false)
}
*/

var_dump(Yaconf::__debug_info("app.missing")); // NULL
?>
